def f(g, mode='zeros'):
    H,W=len(g),len(g[0])
    seen=[[False]*W for _ in range(H)]
    for i in range(H):
        for j in (0,W-1):
            if g[i][j]==0 and not seen[i][j]: st=[(i,j)]; seen[i][j]=True
            while st:
                y,x=st.pop()
                for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<H and 0<=nx<W and g[ny][nx]==0 and not seen[ny][nx]:
                        seen[ny][nx]=True; st.append((ny,nx))
    out=[row[:] for row in g]
    for i in range(H):
        for j in range(W):
            if g[i][j]==0 and not seen[i][j]:
                if mode=='zeros': out[i][j]=8
                elif mode=='all': out[i][j]=8
                elif mode=='zeros_keep2': out[i][j]=8
                elif mode=='swap': out[i][j]=2; out=[[2 if v==8 else v for v in r] for r in out]
