import numpy as np, collections, json, os, re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); T=G['Test input']
def find_frames(g):
    H,W=len(g),len(g[0]); res=[]; seen=set()
    for i in range(H):
        for j in range(W):
            if g[i][j]==2 and (i,j) not in seen:
                q=collections.deque([(i,j)]); seen.add((i,j)); pts=[]
                while q:
                    y,x=q.popleft(); pts.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==2 and (ny,nx) not in seen:
                            seen.add((ny,nx)); q.append((ny,nx))
                ys=[p[0] for p in pts]; xs=[p[1] for p in pts]
                y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
                if y1-y0>=2 and x1-x0>=2:
                    ok=all(g[y0][x]==2 for x in range(x0,x1+1))and all(g[y1][x]==2 for x in range(x0,x1+1)) \
                        and all(g[y][x0]==2 for y in range(y0,y1+1)) and all(g[y][x1]==2 for y in range(y0,y1+1))
                    if ok: res.append((y0,y1,x0,x1))
    return res
def fdemo(g):
    o=[r[:] for r in g]
    for (y0,y1,x0,x1) in find_frames(g):
        twos=[(i,j) for i in range(y0+1,y1) for j in range(x0+1,x1) if g[i][j]==2]
        fill = 8 if not twos else (twos[0][0]-y0-1)+(twos[0][1]-x0-1)
        for i in range(y0+1,y1):
            for j in range(x0+1,x1):
                if g[i][j]==0: o[i][j]=fill
    return o
